	'price_4_p' => 'EUR 85',
	'price_4_v' => 'Sport check',
	'price_4_w' => 'Running, cycling or swimming movement review and treatment',
	'price_5_len' => '5 × 40 min',
	'price_5_p' => 'EUR 320',
	'price_5_v' => 'Five follow-ups',
	'price_5_w' => 'Five 40-minute follow-ups, used within six months',
